CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', currency text NOT NULL DEFAULT 'INR', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_owner ON public.profiles FOR ALL TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_finsight_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END; $$;
CREATE TRIGGER finsight_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_finsight_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'display_name','') FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, file_path text NOT NULL, file_size bigint NOT NULL, mime_type text NOT NULL, file_hash text NOT NULL, status text NOT NULL DEFAULT 'uploaded' CHECK (status IN ('uploaded','extracting','review','processed','failed')), document_type text NOT NULL DEFAULT 'statement', currency text NOT NULL DEFAULT 'INR', extracted_text text NOT NULL DEFAULT '', structured_data jsonb NOT NULL DEFAULT '{}', warnings jsonb NOT NULL DEFAULT '[]', explanation text, error_message text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,file_hash), UNIQUE(id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_owner ON public.documents FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, document_id uuid NOT NULL, date date NOT NULL, description text NOT NULL, reference text, debit numeric(18,2), credit numeric(18,2), balance numeric(18,2), category text NOT NULL DEFAULT 'Uncategorised', currency text NOT NULL DEFAULT 'INR', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (document_id,user_id) REFERENCES public.documents(id,user_id) ON DELETE CASCADE, CHECK (debit IS NULL OR debit >=0), CHECK (credit IS NULL OR credit >=0), CHECK ((coalesce(debit,0)>0 AND coalesce(credit,0)=0) OR (coalesce(credit,0)>0 AND coalesce(debit,0)=0)));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.transactions TO authenticated; GRANT ALL ON public.transactions TO service_role;
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY transactions_owner ON public.transactions FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.financial_summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, document_id uuid NOT NULL UNIQUE, income numeric(18,2) NOT NULL DEFAULT 0, expenses numeric(18,2) NOT NULL DEFAULT 0, net_cash_flow numeric(18,2) NOT NULL DEFAULT 0, transaction_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (document_id,user_id) REFERENCES public.documents(id,user_id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.financial_summaries TO authenticated; GRANT ALL ON public.financial_summaries TO service_role;
ALTER TABLE public.financial_summaries ENABLE ROW LEVEL SECURITY;
CREATE POLICY summaries_owner ON public.financial_summaries FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.chat_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, document_id uuid, role text NOT NULL CHECK (role IN ('user','assistant')), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (document_id,user_id) REFERENCES public.documents(id,user_id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.chat_messages TO authenticated; GRANT ALL ON public.chat_messages TO service_role;
ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY chats_owner ON public.chat_messages FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE INDEX documents_user_created ON public.documents(user_id,created_at DESC);
CREATE INDEX transactions_user_date ON public.transactions(user_id,date DESC);
CREATE INDEX transactions_document ON public.transactions(document_id,user_id);
CREATE INDEX chat_user_created ON public.chat_messages(user_id,created_at);
CREATE INDEX chat_document ON public.chat_messages(document_id,user_id);
CREATE INDEX summary_document_owner ON public.financial_summaries(document_id,user_id);
CREATE FUNCTION public.finsight_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER profiles_update BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.finsight_updated_at();
CREATE TRIGGER documents_update BEFORE UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.finsight_updated_at();
CREATE TRIGGER transactions_update BEFORE UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.finsight_updated_at();
CREATE FUNCTION public.refresh_financial_summary() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE did uuid; uid uuid; BEGIN IF TG_OP='DELETE' THEN did=OLD.document_id; uid=OLD.user_id; ELSE did=NEW.document_id; uid=NEW.user_id; END IF; IF EXISTS(SELECT 1 FROM public.documents WHERE id=did) THEN INSERT INTO public.financial_summaries(user_id,document_id,income,expenses,net_cash_flow,transaction_count) SELECT uid,did,coalesce(sum(credit),0),coalesce(sum(debit),0),coalesce(sum(credit),0)-coalesce(sum(debit),0),count(*) FROM public.transactions WHERE document_id=did ON CONFLICT(document_id) DO UPDATE SET income=excluded.income,expenses=excluded.expenses,net_cash_flow=excluded.net_cash_flow,transaction_count=excluded.transaction_count,updated_at=now(); END IF; RETURN NULL; END; $$;
CREATE TRIGGER transaction_summary AFTER INSERT OR UPDATE OR DELETE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.refresh_financial_summary();
CREATE TABLE public.ai_access_state (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, blocked boolean NOT NULL DEFAULT false, reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_access_state TO authenticated; GRANT ALL ON public.ai_access_state TO service_role;
ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_state_owner ON public.ai_access_state FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY private_document_files ON storage.objects FOR ALL TO authenticated USING (bucket_id='financial-documents' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK (bucket_id='financial-documents' AND (storage.foldername(name))[1]=auth.uid()::text);